"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[4366],{4366(e,s,n){n.d(s,{content:()=>l,description:()=>a,keywords:()=>r,title:()=>i});n(5043);var t=n(579);const i="Quand l'IA lit mal 'au moins un' : la notation textuelle \xe9choue",a="Un \xe9tudiant du Connecticut a perdu des points parce que l'IA a interpr\xe9t\xe9 'au moins un' comme 'seulement un'. Plus de 150 \xe9tudiants ont sign\xe9 une p\xe9tition contre la notation par IA. Voici pourquoi mesurer les actions physiques \xe9limine compl\xe8tement ce probl\xe8me.",r=["probl\xe8mes de notation IA","\xe9valuation bas\xe9e sur les processus","notation laboratoire virtuel","erreurs d'\xe9valuation IA","notation automatis\xe9e des dissertations","laboratoire virtuel","interpr\xe9tation de texte IA","technologie \xe9ducative"],l=(0,t.jsxs)("div",{children:[(0,t.jsx)("p",{children:'Liam Roselle, un \xe9l\xe8ve de terminale \xe0 Amity Regional High School dans le Connecticut, a re\xe7u un sur trois \xe0 deux questions pour un devoir de psychologie AP. Le feedback lui disait qu\'il n\'avait pas fourni de preuves sp\xe9cifiques. Il l\'avait fait. Le probl\xe8me, comme il l\'a finalement d\xe9couvert, \xe9tait que la question demandait "au moins une preuve sp\xe9cifique et pertinente," et il avait cit\xe9 plusieurs \xe9tudes. Le syst\xe8me de notation IA a interpr\xe9t\xe9 "au moins un" comme "seulement un" et l\'a p\xe9nalis\xe9 pour avoir fait plus que le minimum.'}),(0,t.jsxs)("p",{children:["Pour r\xe9cup\xe9rer un seul point sur un devoir, Roselle a d\xfb \xe9crire un email d'appel de trois paragraphes citant la formulation exacte de la question et expliquant la s\xe9mantique de l'expression \"au moins.\" Son professeur a convenu que l'explication avait du sens et a accord\xe9 le point. Mais comme Roselle l'a \xe9crit dans"," ",(0,t.jsx)("a",{href:"https://ctmirror.org/2026/03/05/my-school-is-grading-me-with-ai-it-got-my-grade-wrong/",target:"_blank",rel:"noopener noreferrer",children:"CT Mirror"}),", \"La question qui m\xe9rite d'\xeatre pos\xe9e est de savoir combien d'\xe9tudiants, face \xe0 la m\xeame erreur, ont simplement accept\xe9 la note et sont pass\xe9s \xe0 autre chose.\""]}),(0,t.jsxs)("p",{children:["Il n'est pas seul dans son inqui\xe9tude. Plus de 150 \xe9tudiants d'Amity ont sign\xe9 une p\xe9tition contre la notation par IA dans leur \xe9cole. Et leurs pr\xe9occupations sont \xe9tay\xe9es par la recherche : une \xe9tude pr\xe9sent\xe9e \xe0 la conf\xe9rence de l'American Educational Research Association en 2024 a r\xe9v\xe9l\xe9 que"," ",(0,t.jsx)("a",{href:"https://hechingerreport.org/proof-points-ai-essay-grading/",target:"_blank",rel:"noopener noreferrer",children:"l'IA et les correcteurs humains ne s'accordent exactement que dans environ 40 pour cent des cas"}),", avec un biais constant contre les \xe9crits de haute qualit\xe9. Quand les correcteurs professionnels AP ne sont pas d'accord sur des dissertations, ils font appel \xe0 un m\xe9diateur. Les syst\xe8mes de notation par IA n'offrent pas cette protection par d\xe9faut."]}),(0,t.jsx)("h2",{children:"Pourquoi l'IA a-t-elle du mal avec l'\xe9valuation \xe9crite ?"}),(0,t.jsx)("p",{children:'La mauvaise interpr\xe9tation de "au moins un" n\'est pas un cas limite. Elle r\xe9v\xe8le une limitation fondamentale de la fa\xe7on dont les syst\xe8mes d\'IA traitent le langage naturel. Ces syst\xe8mes fonctionnent par correspondance de motifs : ils apprennent \xe0 quoi ressemblent typiquement les r\xe9ponses "correctes" et notent les soumissions en fonction de leur similarit\xe9 avec ces motifs. Quand un \xe9tudiant exprime une compr\xe9hension correcte d\'une mani\xe8re inattendue, ou fournit plus que le minimum attendu, le syst\xe8me ne le reconna\xeet pas.'}),(0,t.jsx)("p",{children:"Le langage est intrins\xe8quement ambigu. Consid\xe9rez combien de fa\xe7ons un \xe9tudiant pourrait correctement d\xe9crire le m\xeame concept scientifique :"}),(0,t.jsxs)("ul",{children:[(0,t.jsx)("li",{children:'"La solution est devenue rose" vs "L\'indicateur a chang\xe9 de couleur" vs "Un changement de couleur a \xe9t\xe9 observ\xe9"'}),(0,t.jsx)("li",{children:'"Au moins un exemple" pourrait signifier un, deux ou cinq exemples'}),(0,t.jsx)("li",{children:'"La r\xe9action n\xe9cessite de la chaleur" vs "de l\'\xe9nergie thermique est n\xe9cessaire" vs "temp\xe9rature \xe9lev\xe9e"'}),(0,t.jsx)("li",{children:"Diff\xe9rentes orthographes selon que vous avez appris l'anglais britannique ou am\xe9ricain"})]}),(0,t.jsx)("p",{children:"Chacune de ces variations exprime la m\xeame compr\xe9hension scientifique. Un correcteur humain les reconna\xeet comme \xe9quivalentes. Un syst\xe8me d'IA entra\xeen\xe9 sur des formulations particuli\xe8res peut ne pas le faire."}),(0,t.jsx)("p",{children:"La recherche sur la notation automatis\xe9e des dissertations a document\xe9 ces \xe9checs de mani\xe8re extensive. Les syst\xe8mes d'IA p\xe9nalisent les structures de phrases non conventionnelles m\xeame quand le contenu scientifique est exact. Ils r\xe9compensent la prose verbeuse et confiante plut\xf4t que les r\xe9ponses concises et pr\xe9cises. Ils montrent des sch\xe9mas de biais constants qui d\xe9savantagent certains styles d'\xe9criture ind\xe9pendamment des connaissances d\xe9montr\xe9es."}),(0,t.jsx)("h2",{children:"Les co\xfbts cach\xe9s des erreurs de notation par IA"}),(0,t.jsx)("p",{children:"Le cas de Roselle illustre le fardeau cach\xe9 que la notation par IA impose aux \xe9tudiants. Il a r\xe9ussi \xe0 faire appel de sa note, mais cela a n\xe9cessit\xe9 des comp\xe9tences r\xe9dactionnelles acad\xe9miques, la confiance pour d\xe9fier un syst\xe8me automatis\xe9, et un professeur pr\xeat \xe0 examiner l'appel. Combien d'\xe9tudiants manquent d'un ou plusieurs de ces \xe9l\xe9ments ?"}),(0,t.jsx)("p",{children:"Les \xe9tudiants les plus susceptibles d'accepter une note IA incorrecte sont souvent ceux qui ont d\xe9j\xe0 des difficult\xe9s acad\xe9miques. Ils peuvent manquer de confiance pour d\xe9fier l'autorit\xe9, m\xeame l'autorit\xe9 algorithmique. Ils peuvent ne pas avoir les comp\xe9tences r\xe9dactionnelles pour construire un appel persuasif. Ils peuvent avoir appris par exp\xe9rience que leurs objections sont rejet\xe9es. Les syst\xe8mes de notation par IA, pr\xe9sent\xe9s comme objectifs et efficaces, peuvent syst\xe9matiquement d\xe9savantager pr\xe9cis\xe9ment les \xe9tudiants qui ont le plus besoin de soutien."}),(0,t.jsx)("p",{children:"De plus, la demande FOIA de Roselle a r\xe9v\xe9l\xe9 qu'Amity Regional avait achet\xe9 cinq produits d'IA pour un total de 19 216,51 dollars, soit plus de 8 000 dollars de plus que le chiffre de 11 000 dollars que le district avait cit\xe9 publiquement. L'\xe9cart soul\xe8ve des questions sur la transparence et la responsabilit\xe9 dans l'acquisition de technologie \xe9ducative. Quand les districts ne peuvent pas rapporter avec pr\xe9cision quels outils d'IA ils utilisent et \xe0 quel co\xfbt, une surveillance significative devient impossible."}),(0,t.jsx)("h2",{children:"Et si nous \xe9liminions compl\xe8tement l'ambigu\xeft\xe9 ?"}),(0,t.jsx)("p",{children:"Il existe une alternative \xe0 forcer les syst\xe8mes d'IA \xe0 interpr\xe9ter un texte ambigu : \xe9valuer les actions au lieu des mots. Quand un \xe9tudiant effectue un titrage dans un laboratoire virtuel, il n'y a pas d'ambigu\xeft\xe9 sur le fait qu'il ait ajout\xe9 le r\xe9actif goutte \xe0 goutte pr\xe8s du point final. Soit il l'a fait, soit il ne l'a pas fait. Le syst\xe8me n'a pas besoin d'analyser sa description ; il observe directement sa technique."}),(0,t.jsx)("p",{children:"C'est le principe derri\xe8re l'\xe9valuation bas\xe9e sur les processus. Au lieu de demander aux \xe9tudiants de d\xe9crire ce qu'ils feraient et ensuite d'analyser leur langage, vous observez ce qu'ils font r\xe9ellement et vous le mesurez. La diff\xe9rence est profonde :"}),(0,t.jsxs)("ul",{children:[(0,t.jsxs)("li",{children:[(0,t.jsx)("strong",{children:"Bas\xe9 sur le texte :"})," \"J'ai pipett\xe9 2,5 millilitres de la solution\" doit \xeatre interpr\xe9t\xe9. Voulaient-ils dire exactement 2,5 ? Approximativement 2,5 ? Ont-ils d\xe9crit l'action qu'ils ont prise ou l'action qu'ils avaient l'intention de prendre ?"]}),(0,t.jsxs)("li",{children:[(0,t.jsx)("strong",{children:"Bas\xe9 sur les processus :"})," La pipette virtuelle a enregistr\xe9 2,47 mL transf\xe9r\xe9s. Aucune interpr\xe9tation requise."]})]}),(0,t.jsxs)("p",{children:["Le programme"," ",(0,t.jsx)("a",{href:"https://www.dreamscapelearn.com/research",target:"_blank",rel:"noopener noreferrer",children:"Dreamscape Learn"})," ","de l'Universit\xe9 d'\xc9tat de l'Arizona d\xe9montre cette approche \xe0 grande \xe9chelle. Les \xe9tudiants r\xe9solvent des probl\xe8mes biologiques dans des environnements VR immersifs, et le syst\xe8me les note sur leur cheminement de raisonnement \xe0 travers le probl\xe8me, pas sur des explications \xe9crites de ce qu'ils ont fait. Les premiers r\xe9sultats montrent que les \xe9tudiants dans ces sections bas\xe9es sur les processus obtiennent de meilleures notes et une meilleure r\xe9tention que leurs pairs dans les cours conventionnels."]}),(0,t.jsx)("h2",{children:"La physique n'a pas d'ambigu\xeft\xe9 s\xe9mantique"}),(0,t.jsx)("p",{children:"L'avantage fondamental de l'\xe9valuation bas\xe9e sur les processus est que les actions physiques sont d\xe9finies. Quand un \xe9tudiant incline un b\xe9cher, l'angle d'inclinaison est mesurable. Quand il applique de la chaleur, le changement de temp\xe9rature suit une physique pr\xe9visible. Quand il mesure un volume, la mesure a une valeur sp\xe9cifique. Il n'y a pas de synonymes pour les actions physiques."}),(0,t.jsx)("p",{children:"C'est pourquoi nous avons construit WhimsyLabs autour d'un moteur physique propri\xe9taire plut\xf4t que d'animations script\xe9es. Nos simulations suivent les quantit\xe9s physiques r\xe9elles : le volume de liquide dans un conteneur, le timing pr\xe9cis des ajouts, la r\xe9gularit\xe9 de la technique. Quand nous \xe9valuons la performance des \xe9tudiants, nous comparons leurs actions \xe0 la technique correcte, pas leurs descriptions aux phrases attendues."}),(0,t.jsx)("p",{children:"Un \xe9tudiant d'Allemagne, du Japon ou d'Espagne effectue le m\xeame mouvement de pipetage. Un \xe9tudiant qui parle anglais comme langue seconde d\xe9montre la m\xeame compr\xe9hension en agitant un ballon au bon moment. Le langage universel de la proc\xe9dure scientifique transcende les ambigu\xeft\xe9s qui affectent la notation textuelle par IA."}),(0,t.jsx)("h2",{children:"Qu'en est-il des comp\xe9tences de communication \xe9crite ?"}),(0,t.jsx)("p",{children:"Une question l\xe9gitime se pose : l'\xe9ducation scientifique ne devrait-elle pas \xe9galement d\xe9velopper des comp\xe9tences de communication \xe9crite ? La capacit\xe9 de d\xe9crire clairement les proc\xe9dures scientifiques est pr\xe9cieuse."}),(0,t.jsx)("p",{children:"La r\xe9ponse est oui, mais avec une distinction importante. La communication \xe9crite est une comp\xe9tence qui m\xe9rite d'\xeatre d\xe9velopp\xe9e, et elle peut \xeatre \xe9valu\xe9e quand c'est l'objectif explicite. Le probl\xe8me avec les \xe9valuations \xe9crites not\xe9es par IA est qu'elles confondent la compr\xe9hension scientifique avec la capacit\xe9 d'\xe9criture. Un \xe9tudiant qui comprend profond\xe9ment le titrage mais \xe9crit maladroitement est p\xe9nalis\xe9 non pas pour des conceptions erron\xe9es scientifiques mais pour des erreurs linguistiques. Un \xe9tudiant qui \xe9crit couramment mais comprend superficiellement peut recevoir des notes plus \xe9lev\xe9es."}),(0,t.jsx)("p",{children:"L'\xe9valuation bas\xe9e sur les processus s\xe9pare ces pr\xe9occupations. Quand vous voulez \xe9valuer la technique scientifique, \xe9valuez la technique directement. Quand vous voulez \xe9valuer la communication scientifique, \xe9valuez la communication explicitement. Ne pr\xe9tendez pas mesurer l'un tout en mesurant r\xe9ellement l'autre."}),(0,t.jsx)("h2",{children:"La vraie promesse de l'IA dans l'\xe9valuation"}),(0,t.jsx)("p",{children:"Les \xe9checs de la notation textuelle par IA ne signifient pas que l'IA n'a pas de r\xf4le dans l'\xe9valuation \xe9ducative. Ils signifient que l'IA devrait \xeatre appliqu\xe9e aux t\xe2ches o\xf9 elle excelle plut\xf4t qu'aux t\xe2ches o\xf9 elle a du mal."}),(0,t.jsx)("p",{children:"L'IA excelle dans la reconnaissance de motifs dans les donn\xe9es structur\xe9es, le suivi des s\xe9quences proc\xe9durales, l'identification d'erreurs techniques sp\xe9cifiques et l'analyse de grands ensembles de donn\xe9es pour trouver des patterns. Ces capacit\xe9s sont parfaitement adapt\xe9es \xe0 l'\xe9valuation bas\xe9e sur les processus, o\xf9 les donn\xe9es sont sans ambigu\xeft\xe9 et les patterns sont bien d\xe9finis."}),(0,t.jsx)("p",{children:"Dans WhimsyLabs, notre tuteur IA WhimsyCat utilise les donn\xe9es de processus pour fournir un feedback en temps r\xe9el. Quand un \xe9tudiant se pr\xe9cipite dans une proc\xe9dure, WhimsyCat le remarque et sugg\xe8re de ralentir. Quand un \xe9tudiant r\xe9p\xe8te la m\xeame erreur plusieurs fois, WhimsyCat explique pourquoi l'approche ne fonctionne pas et offre des alternatives. Ce feedback est possible parce que les donn\xe9es sont pr\xe9cises. WhimsyCat n'essaie pas de deviner si un \xe9tudiant a compris quelque chose \xe0 partir d'une phrase ambigu\xeb ; il a observ\xe9 exactement ce que l'\xe9tudiant a fait."}),(0,t.jsx)("h2",{children:"Ce que r\xe9v\xe8le l'appel de Roselle"}),(0,t.jsx)("p",{children:"Revenons au cas de Liam Roselle. Son appel r\xe9ussi lui a demand\xe9 d'expliquer, avec des citations de la formulation exacte de la question, pourquoi l'interpr\xe9tation de l'IA \xe9tait erron\xe9e. Son professeur a not\xe9 que \"comme les outils de notation IA et les humains peuvent interpr\xe9ter diff\xe9remment les questions et les r\xe9ponses, et sont faillibles,\" il \xe9tait content qu'ils aient eu l'occasion d'en discuter."}),(0,t.jsx)("p",{children:"Cette d\xe9claration r\xe9v\xe8le involontairement le probl\xe8me central. Quand l'\xe9valuation n\xe9cessite l'interpr\xe9tation du langage, le d\xe9saccord est in\xe9vitable. Les humains sont en d\xe9saccord entre eux. L'IA est en d\xe9saccord avec les humains. L'IA est en d\xe9saccord avec elle-m\xeame quand on lui pr\xe9sente des versions reformul\xe9es d'un contenu identique. Le syst\xe8me est instable parce que le langage est instable."}),(0,t.jsx)("p",{children:"Mais une technique de pipetage ne n\xe9cessite pas d'interpr\xe9tation. Un point final de titrage ne n\xe9cessite pas d'interpr\xe9tation. L'angle d'un b\xe9cher, le timing d'un ajout, la r\xe9gularit\xe9 d'une main : ce sont des faits, pas des interpr\xe9tations. L'\xe9valuation construite sur des faits plut\xf4t que sur des interpr\xe9tations produit des r\xe9sultats coh\xe9rents et d\xe9fendables qui ne n\xe9cessitent pas d'appels."}),(0,t.jsx)("h2",{children:"La voie \xe0 suivre"}),(0,t.jsx)("p",{children:"Le conseil d'administration d'Amity Regional High School devait voter sur le budget de l'ann\xe9e prochaine le 9 mars 2026. Roselle leur avait envoy\xe9 des emails quotidiens pendant plus de deux semaines, leur demandant de prendre au s\xe9rieux ce que 150 \xe9tudiants disaient et ce qu'un \xe9tudiant avait d\xfb faire pour r\xe9cup\xe9rer un point qu'il avait d\xe9j\xe0 gagn\xe9."}),(0,t.jsx)("p",{children:"Sa situation refl\xe8te un d\xe9fi plus large auquel l'\xe9ducation est confront\xe9e : la pression d'adopter l'IA pour des gains d'efficacit\xe9 sans consid\xe9rer ad\xe9quatement o\xf9 l'IA fonctionne r\xe9ellement bien. L'interpr\xe9tation de texte est difficile parce que le texte est ambigu. Ce n'est pas une limitation temporaire en attente d'une perc\xe9e. C'est une propri\xe9t\xe9 fondamentale du langage naturel."}),(0,t.jsx)("p",{children:"La solution n'est pas d'abandonner l'IA mais de la d\xe9ployer de mani\xe8re appropri\xe9e. L'\xe9valuation bas\xe9e sur les processus dans les laboratoires virtuels repr\xe9sente un tel d\xe9ploiement appropri\xe9. Quand les \xe9tudiants d\xe9montrent leur compr\xe9hension par l'action plut\xf4t que par la description, l'IA peut les \xe9valuer avec pr\xe9cision, \xe9quit\xe9 et \xe0 grande \xe9chelle. L'ambigu\xeft\xe9 s\xe9mantique qui a pi\xe9g\xe9 Roselle dispara\xeet enti\xe8rement."}),(0,t.jsx)("p",{children:"L'IA ne peut pas mal lire une technique de pipetage parce qu'il n'y a rien \xe0 mal lire. L'action s'est produite correctement ou non. Dans cette clart\xe9 r\xe9side un meilleur avenir pour l'\xe9valuation \xe9ducative."}),(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)("h2",{children:"Articles connexes"}),(0,t.jsxs)("ul",{children:[(0,t.jsx)("li",{children:(0,t.jsx)("a",{href:"/fr/blog/ai-assessment-crisis-solution",children:"L'IA et la crise de l'\xe9valuation : Comment les donn\xe9es de processus changent tout"})}),(0,t.jsx)("li",{children:(0,t.jsx)("a",{href:"/fr/blog/edtech-critics-right-passive-learning-vs-active-labs",children:"Les critiques ont raison : La plupart des EdTech sont inutiles"})}),(0,t.jsx)("li",{children:(0,t.jsx)("a",{href:"/fr/blog/vr-stem-education-research-pedagogical-scaffolding",children:"Une nouvelle recherche VR confirme : La technologie sans p\xe9dagogie \xe9choue"})}),(0,t.jsx)("li",{children:(0,t.jsx)("a",{href:"/fr/blog/whimsycat-ai-tutor-transforming-science-education",children:"D\xe9couvrez WhimsyCat : Notre innovation IA dans l'\xe9ducation scientifique"})})]})]}),(0,t.jsxs)("div",{className:"references-section",children:[(0,t.jsx)("h3",{children:"R\xe9f\xe9rences"}),(0,t.jsxs)("ul",{className:"references-list",children:[(0,t.jsxs)("li",{children:["Roselle, L. (2026, 5 mars). My school is grading me with AI. It got my grade wrong."," ",(0,t.jsx)("em",{children:"CT Mirror"}),"."," ",(0,t.jsx)("a",{href:"https://ctmirror.org/2026/03/05/my-school-is-grading-me-with-ai-it-got-my-grade-wrong/",target:"_blank",rel:"noopener noreferrer",children:"https://ctmirror.org/2026/03/05/my-school-is-grading-me-with-ai-it-got-my-grade-wrong/"})]},"ref-1"),(0,t.jsxs)("li",{children:["Barshay, J. (2024). AI essay grading: What the research shows."," ",(0,t.jsx)("em",{children:"The Hechinger Report"}),"."," ",(0,t.jsx)("a",{href:"https://hechingerreport.org/proof-points-ai-essay-grading/",target:"_blank",rel:"noopener noreferrer",children:"https://hechingerreport.org/proof-points-ai-essay-grading/"})]},"ref-2"),(0,t.jsxs)("li",{children:["Dreamscape Learn. (2024). Research and outcomes at Arizona State University."," ",(0,t.jsx)("a",{href:"https://www.dreamscapelearn.com/research",target:"_blank",rel:"noopener noreferrer",children:"https://www.dreamscapelearn.com/research"})]},"ref-3"),(0,t.jsxs)("li",{children:["Keep Amity Human. (2026). FOIA documents on AI tools in Amity Regional School District."," ",(0,t.jsx)("a",{href:"https://keepamityhuman.org/foia.html",target:"_blank",rel:"noopener noreferrer",children:"https://keepamityhuman.org/foia.html"})]},"ref-4"),(0,t.jsx)("li",{children:"American Educational Research Association. (2024). Research on automated essay scoring reliability and bias."},"ref-5")]})]})]})}}]);
